Issue Vaccination Certificate.code:
// Issue a vaccination certificate as a Verifiable Credential.
issueCredential({
  credential: {
    '@context': ['https://www.w3.org/2018/credentials/v1'],
    type: ['VerifiableCredential', 'VaccinationCertificate'],
    // DID of the issuing health authority.
    issuer: $.data.issuerDid,
    issuanceDate: new Date().toISOString(),
    credentialSubject: {
      id: $.data.recipientDid,
      name: $.data.patientName,
      vaccine: $.data.vaccine, // e.g. 'Measles-Rubella'
      dose: $.data.doseNumber,
      dateOfVaccination: $.data.vaccinationDate,
      facility: $.data.facilityName,
    },
  },
  // Credential schema registered in the credential-schema service.
  credentialSchemaId: $.data.schemaId,
  credentialSchemaVersion: '1.0.0',
  tags: ['immunization'],
});

Issue Benefit Eligibility Credential.code:
// Issue a programme-enrolment credential to a beneficiary.
issueCredential({
  credential: {
    '@context': ['https://www.w3.org/2018/credentials/v1'],
    type: ['VerifiableCredential', 'BenefitEligibilityCredential'],
    issuer: $.data.issuerDid,
    issuanceDate: new Date().toISOString(),
    expirationDate: $.data.validUntil,
    credentialSubject: {
      id: $.data.beneficiaryDid,
      name: $.data.beneficiaryName,
      programme: $.data.programmeName, // e.g. 'Child Support Grant'
      householdId: $.data.householdId,
    },
  },
  credentialSchemaId: $.data.schemaId,
  credentialSchemaVersion: '1.0.0',
  tags: ['social-protection'],
});

Download Credential PDF.code:
// Download a credential rendered with a template.
downloadCredential(
  // 1) Credential id.
  $.data.credentialId,
  // 2) Template used to render it.
  { templateId: $.data.templateId }
);

Search Credentials By Subject.code:
// Find all credentials issued to one person.
post('credentials/search', {
  subject: { id: $.data.recipientDid },
  issuer: { id: $.data.issuerDid },
});
